/* Volta Studio — Design System */
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;500;600;700;800;900&family=Inter:wght@300;400;500;600&display=swap');

:root {
  --bg: #F5F2ED;
  --fg: #1A1A1A;
  --accent-warm: #C4A77D;
  --accent-terracotta: #B86F4E;
  --accent-sage: #7A8B6F;
  --accent-sand: #D4C5A9;
  --border: #E5E0D8;
  --muted: #8A857D;
  --font-serif: 'Playfair Display', Georgia, serif;
  --font-sans: 'Inter', system-ui, sans-serif;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  background: var(--bg);
  color: var(--fg);
  font-family: var(--font-sans);
  font-weight: 400;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

::selection { background: var(--accent-warm); color: var(--bg); }

/* Typography */
h1, h2, h3, h4 {
  font-family: var(--font-serif);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.5rem, 8vw, 6rem); }
h2 { font-size: clamp(2rem, 5vw, 3.5rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); }
h4 { font-size: 1.25rem; }

p { max-width: 65ch; }

a { color: inherit; text-decoration: none; }

/* Header / Nav */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 1.5rem 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--bg);
  border-bottom: 1px solid transparent;
  transition: border-color 0.3s;
}

.site-header.scrolled { border-color: var(--border); }

.logo {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  cursor: pointer;
}

.nav-desktop {
  display: none;
  gap: 2.5rem;
}

.nav-desktop a {
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  position: relative;
}

.nav-desktop a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 1px;
  background: var(--fg);
  transition: width 0.3s ease;
}

.nav-desktop a:hover::after { width: 100%; }

.nav-mobile-toggle {
  display: flex;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
  z-index: 200;
}

.nav-mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--fg);
  transition: transform 0.3s, opacity 0.3s;
}

.nav-mobile-toggle.active span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.nav-mobile-toggle.active span:nth-child(2) { opacity: 0; }
.nav-mobile-toggle.active span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

.nav-overlay {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 150;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 2rem;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.nav-overlay.active {
  opacity: 1;
  pointer-events: all;
}

.nav-overlay a {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: 700;
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.4s ease, transform 0.4s ease;
}

.nav-overlay.active a {
  opacity: 1;
  transform: translateY(0);
}

.nav-overlay a:nth-child(1) { transition-delay: 0.1s; }
.nav-overlay.active a:nth-child(1) { transition-delay: 0.15s; }
.nav-overlay a:nth-child(2) { transition-delay: 0.15s; }
.nav-overlay.active a:nth-child(2) { transition-delay: 0.2s; }
.nav-overlay a:nth-child(3) { transition-delay: 0.2s; }
.nav-overlay.active a:nth-child(3) { transition-delay: 0.25s; }
.nav-overlay a:nth-child(4) { transition-delay: 0.25s; }
.nav-overlay.active a:nth-child(4) { transition-delay: 0.3s; }
.nav-overlay a:nth-child(5) { transition-delay: 0.3s; }
.nav-overlay.active a:nth-child(5) { transition-delay: 0.35s; }

/* Main layout */
main { padding-top: 80px; }

.container {
  width: 100%;
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 2rem;
}

.container-narrow {
  max-width: 720px;
  margin: 0 auto;
  padding: 0 2rem;
}

/* Section spacing */
section { padding: 5rem 0; }

.section-label {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 2rem;
}

/* Hero */
.hero {
  padding: 4rem 0 6rem;
}

.hero h1 { margin-bottom: 2rem; }

.hero-sub {
  font-size: 1.125rem;
  color: var(--muted);
  max-width: 50ch;
}

/* Media Showcase */
.media-showcase {
  padding: 4rem 0;
}

.media-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

.media-block {
  aspect-ratio: 16/10;
  border-radius: 8px;
}

.media-block:nth-child(1) { background: var(--accent-terracotta); }
.media-block:nth-child(2) { background: var(--accent-sage); }
.media-block:nth-child(3) { background: var(--accent-sand); }

/* Client Marquee */
.client-marquee {
  padding: 4rem 0;
  overflow: hidden;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.marquee-track {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.marquee-row {
  display: flex;
  gap: 0;
  white-space: nowrap;
}

.marquee-row.left { animation: scroll-left 30s linear infinite; }
.marquee-row.right { animation: scroll-right 30s linear infinite; }

@keyframes scroll-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes scroll-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

.marquee-item {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 3vw, 2rem);
  font-weight: 700;
  padding: 0 2rem;
  display: flex;
  align-items: center;
  gap: 2rem;
}

.marquee-item::after {
  content: '◦';
  color: var(--accent-warm);
}

/* About */
.about {
  padding: 6rem 0;
}

.about p {
  font-size: 1.25rem;
  line-height: 1.8;
  margin-bottom: 2rem;
}

.about-highlight {
  font-size: 1.5rem;
  color: var(--muted);
  font-style: italic;
}

/* Founder Letter */
.founder-letter {
  padding: 6rem 0;
}

.founder-letter h1 {
  margin-bottom: 4rem;
}

.letter-body {
  font-size: 1.25rem;
  line-height: 2;
}

.letter-body p { margin-bottom: 2.5rem; }

.letter-body p:first-of-type::first-letter {
  font-family: var(--font-serif);
  font-size: 4rem;
  float: left;
  line-height: 1;
  margin-right: 1rem;
  margin-top: 0.5rem;
}

.letter-signature {
  font-family: var(--font-serif);
  font-size: 2rem;
  margin-top: 4rem;
}

/* Services */
.services { padding: 6rem 0; }

.services h1 {
  margin-bottom: 1rem;
}

.philosophy-intro {
  font-size: 1.25rem;
  color: var(--muted);
  margin-bottom: 6rem;
}

.philosophy-section {
  display: grid;
  grid-template-columns: 1fr;
  gap: 4rem;
  margin-bottom: 6rem;
}

.philosophy-label {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 1rem;
}

.philosophy-title {
  font-family: var(--font-serif);
  font-size: 3rem;
  font-weight: 800;
  margin-bottom: 1.5rem;
}

.philosophy-text {
  font-size: 1.125rem;
  line-height: 1.8;
}

.divider {
  height: 1px;
  background: var(--border);
  margin: 4rem 0;
}

.service-category {
  margin-bottom: 4rem;
}

.service-category h3 {
  font-family: var(--font-serif);
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 1rem;
}

.service-category p {
  font-size: 1.125rem;
  color: var(--muted);
  line-height: 1.8;
}

/* Clients Grid */
.clients-page { padding: 6rem 0; }

.clients-page h1 {
  margin-bottom: 4rem;
}

.clients-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 3rem;
}

.client-item h4 {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
}

.client-item p {
  font-size: 0.9375rem;
  color: var(--muted);
  line-height: 1.7;
}

/* Contact Page */
.contact-page { padding: 6rem 0; }

.contact-hero h1 {
  font-size: clamp(4rem, 15vw, 12rem);
  line-height: 0.9;
  margin-bottom: 4rem;
}

.contact-links {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.contact-links a {
  font-size: 1.25rem;
  font-weight: 500;
  position: relative;
  display: inline-block;
}

.contact-links a::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 100%;
  height: 1px;
  background: var(--fg);
  transform: scaleX(0);
  transform-origin: right;
  transition: transform 0.3s ease;
}

.contact-links a:hover::after {
  transform: scaleX(1);
  transform-origin: left;
}

/* Footer */
.site-footer {
  padding: 3rem 0;
  border-top: 1px solid var(--border);
}

.footer-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.875rem;
  color: var(--muted);
}

/* Responsive */
@media (min-width: 768px) {
  .nav-desktop { display: flex; }
  .nav-mobile-toggle { display: none; }

  .media-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .philosophy-section {
    grid-template-columns: 1fr 1fr;
  }
}

@media (min-width: 1024px) {
  .container { padding: 0 4rem; }

  .clients-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  h1 { font-size: clamp(3rem, 6vw, 5rem); }
}
